#[inline(always)]
pub(super) fn zero_count(b: u64, m: usize, k: usize) -> u64 {
    let x = b * (m - k) as u64;
    let q = ((x as u128 * INV[m] as u128) >> 64) as u64;
    q + u64::from(x - q * m as u64 >= m as u64)
}
pub fn weight(c: &Challenge) -> usize {
    c.iter().map(|&b| usize::from(b)).sum()
}
pub(super) fn ranks(hash: &[u8; 32]) -> [u64; 4] {
    core::array::from_fn(|j| {
        let start = (51 * j) / 8;
        let shift = (51 * j) % 8;
        (u64::from_le_bytes(hash[start..start + 8].try_into().unwrap()) >> shift)
            & ((1u64 << 51) - 1)
    })
}

pub fn fold(hash: &[u8; 32]) -> Challenge {
    let mut r = ranks(hash);
    let mut b = [INITIAL; 4];
    let mut k = [18usize; 4];
    let mut out = [false; N];
    for m in (1..=64).rev() {
        for j in 0..4 {
            let z = zero_count(b[j], m, k[j]);
            let take = u64::from(r[j] >= z);
            let mask = 0u64.wrapping_sub(take);
            r[j] -= z & mask;
            b[j] = ((b[j] - z) & mask) | (z & !mask);
            k[j] -= take as usize;
            out[64 * j + 64 - m] = take != 0;
        }
    }
    out
}
// Membership must reject the unused suffix of each combinatorial block.
fn inverse(c: &Challenge) -> Option<[u64; 4]> {
    let mut out = [0u64; 4];
    for j in 0..4 {
        if c[64 * j..64 * j + 64].iter().filter(|&&v| v).count() != 18 {
            return None;
        }
        let (mut b, mut k, mut r) = (INITIAL, 18usize, 0u64);
        for m in (1..=64).rev() {
            let z = zero_count(b, m, k);
            if c[64 * j + 64 - m] {
                r += z;
                b -= z;
                k -= 1;
            } else {
                b = z;
            }
        }
        if r >= 1u64 << 51 {
            return None;
        }
        out[j] = r;
    }
    Some(out)
}
pub fn in_c255(c: &Challenge) -> bool {
    inverse(c).is_some()
}
pub fn parity_of(z0: &[i32; N]) -> Challenge {
    core::array::from_fn(|i| z0[i].rem_euclid(2) == 1)
}
