    pub fn digest(rs: [u64; 4]) -> [u8; 32] {
        let mut h = [0; 32];
        for j in 0..4 {
            for i in 0..51 {
                let at = 51 * j + i;
                h[at / 8] |= (((rs[j] >> i) & 1) as u8) << (at % 8);
            }
        }
        h
    }
    #[test]
    fn reference_inverse_and_auxiliary_bits() {
        for (rs, expected) in VECTORS {
            let mut h = digest(rs);
            let c = fold(&h);
            assert_eq!(inverse(&c), Some(rs));
            assert_eq!(weight(&c), 72);
            for i in 0..256 {
                assert_eq!(u8::from(c[i]), expected.as_bytes()[i] - b'0');
            }
            for i in 204..256 {
                h[i / 8] ^= 1 << (i % 8);
                assert_eq!(fold(&h), c);
                h[i / 8] ^= 1 << (i % 8);
            }
            let mut bad = c;
            bad[0] = !bad[0];
            assert!(!in_c255(&bad));
        }
    }
    #[test]
    fn rejects_unused_rank_suffix() {
        let block = [
            false, true, false, true, false, false, false, false, false, false, true, false, false,
            false, false, false, false, true, false, true, false, true, false, false, false, false,
            false, false, false, false, false, false, false, false, false, true, true, false, true,
            false, false, false, false, false, true, false, false, true, false, false, false,
            false, false, true, true, true, true, true, true, false, true, false, false, false,
        ];
        let c = core::array::from_fn(|i| block[i % 64]);
        assert_eq!(weight(&c), 72);
        assert!(!in_c255(&c));
    }
